import json
import time
import logging
from pathlib import Path
from typing import List, Optional, Dict, Any
from pydantic import BaseModel, Field

logger = logging.getLogger(__name__)


class YouTubeMetadata(BaseModel):
    """Structured YouTube metadata generated by AI."""
    title: str = ""
    description_contextual: str = ""
    description_thematic: str = ""
    description_hashtags: str = ""
    description_keyword_cloud: str = ""
    tags: List[str] = Field(default_factory=list)
    pinned_comment: str = ""

    def format_full_description(self, author_name: Optional[str] = None, original_url: Optional[str] = None) -> str:
        """Combines all description parts into final YouTube description without credits or icons."""
        parts = []
        if self.description_contextual:
            parts.append(self.description_contextual)
        if self.description_thematic:
            parts.append(f"\n{self.description_thematic}")
        if self.description_hashtags:
            parts.append(f"\n{self.description_hashtags}")
        if self.description_keyword_cloud:
            parts.append(f"\n{self.description_keyword_cloud}")

        parts.append(
            "\nAll rights belong to the original creators and artists. "
            "For credit or video removal inquiries, please contact us."
        )
        return "\n".join(parts)


def generate_youtube_metadata(
    frame_paths: List[str],
    gemini_api_key: Optional[str],
    system_prompt: str,
    detected_dance: str = "Dance Cover",
    jina_title: str = "",
    jina_description: str = "",
    author_name: str = "Unknown",
    candidate_models: Optional[List[str]] = None,
    sleep_seconds: int = 3,
) -> YouTubeMetadata:
    """
    Uses Gemini Vision to analyze video frames and generate SEO-optimized
    YouTube metadata (title, description, tags, pinned_comment).

    Falls back to template-based metadata if AI generation fails.
    """
    if not gemini_api_key or not frame_paths:
        logger.info("No API key or frames; returning template metadata.")
        return _fallback_metadata(detected_dance, jina_title)

    if not candidate_models:
        candidate_models = ["gemini-3.1-flash-lite", "gemini-3.5-flash-lite"]

    # Build user prompt with extra context
    user_context_parts = [
        f"Dance style detected: {detected_dance}",
    ]
    if jina_title:
        user_context_parts.append(f"Original video title: {jina_title}")
    if jina_description:
        user_context_parts.append(f"Original video description: {jina_description}")
    if author_name and author_name != "Unknown":
        user_context_parts.append(f"Original creator: {author_name}")

    user_prompt = (
        "Analyze the following dance video frames and generate YouTube Shorts metadata.\n\n"
        "Context:\n" + "\n".join(user_context_parts) +
        "\n\nInstruction: Apply the system rules and fill the JSON structure."
    )

    try:
        from google import genai
        from PIL import Image
        from .ai_keywords import filter_available_models

        client = genai.Client(api_key=gemini_api_key)
        images = [Image.open(f) for f in frame_paths if Path(f).exists()]

        if not images:
            return _fallback_metadata(detected_dance, jina_title)

        contents = [system_prompt, user_prompt] + images
        active_candidates = filter_available_models(client, candidate_models)

        for model_name in active_candidates:
            try:
                logger.info("Generating metadata with model '%s'...", model_name)
                response = client.models.generate_content(
                    model=model_name,
                    contents=contents,
                )
                if sleep_seconds > 0:
                    time.sleep(sleep_seconds)

                text = response.text.strip()
                # Strip markdown code fences
                if text.startswith("```json"):
                    text = text[7:]
                if text.startswith("```"):
                    text = text[3:]
                if text.endswith("```"):
                    text = text[:-3]
                text = text.strip()

                data = json.loads(text)
                return _parse_ai_response(data)
            except Exception as e:
                logger.warning("Metadata model '%s' failed: %s", model_name, e)
                if sleep_seconds > 0:
                    time.sleep(sleep_seconds)

    except Exception as e:
        logger.warning("Metadata generation failed: %s", e)

    return _fallback_metadata(detected_dance, jina_title)


def _parse_ai_response(data: Dict[str, Any]) -> YouTubeMetadata:
    """Parses AI JSON response into structured YouTubeMetadata."""
    desc = data.get("description", {})

    # Parse tags: can be string (comma-separated) or list
    raw_tags = data.get("tags", "")
    if isinstance(raw_tags, str):
        tags = [t.strip() for t in raw_tags.split(",") if t.strip()]
    elif isinstance(raw_tags, list):
        tags = [str(t).strip() for t in raw_tags if str(t).strip()]
    else:
        tags = []

    return YouTubeMetadata(
        title=data.get("title", ""),
        description_contextual=desc.get("contextual_summary", "") if isinstance(desc, dict) else str(desc),
        description_thematic=desc.get("thematic_seo", "") if isinstance(desc, dict) else "",
        description_hashtags=desc.get("hashtags", "") if isinstance(desc, dict) else "",
        description_keyword_cloud=desc.get("keyword_cloud", "") if isinstance(desc, dict) else "",
        tags=tags[:20],
        pinned_comment=data.get("pinned_comment", ""),
    )


def _fallback_metadata(detected_dance: str, jina_title: str = "") -> YouTubeMetadata:
    """Returns template-based metadata when AI is unavailable."""
    title = jina_title if jina_title else f"{detected_dance} Dance Cover #dance #dancecover #shorts"
    return YouTubeMetadata(
        title=title[:100],
        description_contextual=f"Amazing {detected_dance} dance cover performance!",
        description_hashtags="#dance #dancecover #shorts #dancechallenge #choreography "
                            "#kpopdance #streetdance #douyindance #viralshorts "
                            "#dancetutorial #hiphopdance #urbandance #dancemoves "
                            "#dancetrend #dancover_uni",
        tags=["dance cover", "shorts", "dance challenge", "choreography",
              "kpop dance", "street dance", "douyin dance", "tiktok dance",
              "viral dance", "dance performance"],
        pinned_comment=f"What do you think of this {detected_dance}? Rate 1-10! 🔥",
    )
